import { LogicWrapper, MakeLogicType, afterMount, connect, kea, key, path, props, propsChanged, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { projectLogic } from 'scenes/projectLogic'

import * as api from '../../generated/api'
import type { SignalReportCheckApi } from '../../generated/api.schemas'

export interface MonitoringRowLogicProps {
    reportId: string
    loadChecks: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface monitoringRowLogicValues {
    currentProjectId: number | null // projectLogic
    reportChecks: SignalReportCheckApi[] | null
    reportChecksLoadFailed: boolean
    reportChecksLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface monitoringRowLogicActions {
    loadReportChecks: (_: void) => void
    loadReportChecksFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadReportChecksSuccess: (
        reportChecks: SignalReportCheckApi[],
        payload?: void
    ) => {
        reportChecks: SignalReportCheckApi[]
        payload?: void
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface monitoringRowLogicMeta {
    key: string
}

export type monitoringRowLogicType = MakeLogicType<
    monitoringRowLogicValues,
    monitoringRowLogicActions,
    MonitoringRowLogicProps,
    monitoringRowLogicMeta
>

export const monitoringRowLogic: LogicWrapper<monitoringRowLogicType> = kea<monitoringRowLogicType>([
    props({} as MonitoringRowLogicProps),
    key((props) => props.reportId),
    path((key) => ['products', 'signals', 'inbox', 'logics', 'monitoringRowLogic', key]),
    connect(() => ({ values: [projectLogic, ['currentProjectId']] })),
    loaders(({ props, values }) => ({
        reportChecks: [
            null as SignalReportCheckApi[] | null,
            {
                loadReportChecks: async (_: void, breakpoint) => {
                    if (values.currentProjectId == null) {
                        return []
                    }
                    try {
                        const response = await api.signalsReportChecksList(
                            String(values.currentProjectId),
                            props.reportId
                        )
                        breakpoint()
                        return response.results
                    } catch (error) {
                        breakpoint()
                        throw error
                    }
                },
            },
        ],
    })),
    reducers({
        reportChecksLoadFailed: [
            false,
            {
                loadReportChecks: () => false,
                loadReportChecksSuccess: () => false,
                loadReportChecksFailure: () => true,
            },
        ],
    }),
    propsChanged(({ actions, props }, oldProps) => {
        if (props.loadChecks && !oldProps.loadChecks) {
            actions.loadReportChecks()
        }
    }),
    afterMount(({ actions, props }) => {
        if (props.loadChecks) {
            actions.loadReportChecks()
        }
    }),
])
